insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g6_health_v1'
from (values
('115.26.b.1',3,'Which body system includes the heart, blood vessels and blood?','["circulatory system", "nervous system", "digestive system", "skeletal system"]'::jsonb,0,'The circulatory system moves blood throughout the body.','original'),
('115.26.b.1',3,'Which body system uses the brain, spinal cord and nerves to send messages?','["endocrine system", "nervous system", "respiratory system", "muscular system"]'::jsonb,1,'The nervous system controls and coordinates the body.','original'),
('115.26.b.11',3,'Which is an example of an unintentional injury?','["a threat sent online", "a prank meant to harm", "a fall from a skateboard", "a planned fight"]'::jsonb,2,'Unintentional injuries happen by accident.','original'),
('115.26.b.11',3,'A good safety skill to prevent injuries at home is to...','["ignore smoke alarms", "run on wet floors", "leave toys on the stairs", "keep walkways clear and store sharp objects safely"]'::jsonb,3,'Prevention reduces accidents.','original'),
('115.26.b.2.A',3,'Brushing and flossing daily is a choice with which long-term effect?','["healthier teeth and gums", "weaker bones", "no effect on health", "instant weight gain"]'::jsonb,0,'Good dental habits protect teeth over a lifetime.','original'),
('115.26.b.2.A',3,'Skipping sleep to play games might cause which immediate effect?','["stronger muscles right away", "feeling tired and unable to focus the next day", "better grades overnight", "no change in mood"]'::jsonb,1,'Sleep loss has quick effects on focus and mood.','original'),
('115.26.b.2.B',3,'A good criterion for judging whether a health website is reliable is whether it...','["has flashy ads", "promises a miracle cure", "is written by qualified experts and cites sources", "was shared by a stranger"]'::jsonb,2,'Credible sources show expertise and evidence.','original'),
('115.26.b.2.B',3,'Which web address ending is most likely to belong to a government health agency?','[".shop", ".fun", ".biz", ".gov"]'::jsonb,3,'Government sites end in .gov.','original'),
('115.26.b.2.C',3,'A student who uses health information to choose a nutritious breakfast is showing...','["decision-making based on information", "guessing", "peer pressure", "ignoring facts"]'::jsonb,0,'Using facts to choose is good decision-making.','original'),
('115.26.b.2.C',3,'Before making a health decision, a student should...','["pick the first option", "gather accurate information and consider the possible results", "do what an ad says", "ask nobody and guess"]'::jsonb,1,'Informed decisions consider results.','original'),
('115.26.b.2.D',3,'A current health-related issue for many teens is...','["too many vitamins", "a shortage of oxygen", "too much screen time and too little sleep", "too much sunshine"]'::jsonb,2,'Guidelines address sleep and screen time.','original'),
('115.26.b.2.D',3,'Health agencies recommend that most children get at least this much daily activity:','["5 minutes", "10 minutes", "2 hours of sitting", "60 minutes"]'::jsonb,3,'The recommendation is 60 minutes of moderate to vigorous activity.','original'),
('115.26.b.2.E',3,'Immunizations help prevent illness by...','["training the body to fight specific germs", "curing every disease", "making germs stronger", "replacing sleep"]'::jsonb,0,'Vaccines prepare the immune system.','original'),
('115.26.b.2.E',3,'A preventive health measure is a...','["missed appointment", "yearly checkup", "skipped meal", "late night"]'::jsonb,1,'Checkups catch problems early.','original'),
('115.26.b.2.F',3,'When you have a fever and feel sick, you should...','["share your drink with friends", "ignore it", "rest, drink fluids and tell an adult", "go to a crowded party"]'::jsonb,2,'Resting and telling an adult help recovery and protect others.','original'),
('115.26.b.2.F',3,'To avoid spreading an illness at school, a sick student should...','["come to school and cough on others", "share tissues", "skip handwashing", "stay home until well"]'::jsonb,3,'Staying home protects others.','original'),
('115.26.b.2.G',3,'Ticks can spread an illness called...','["Lyme disease", "dehydration", "a broken bone", "a sprain"]'::jsonb,0,'Ticks are vectors for Lyme disease.','original'),
('115.26.b.2.G',3,'A good way to prevent mosquito-borne illness is to...','["wear dark shorts at dusk only", "use repellent and remove standing water", "avoid all repellent", "leave buckets of water outside"]'::jsonb,1,'Mosquitoes breed in standing water.','original'),
('115.26.b.3.A',3,'A healthy way to communicate anger is to...','["give the silent treatment forever", "call people names", "use I-statements and speak calmly", "slam doors"]'::jsonb,2,'I-statements express feelings respectfully.','original'),
('115.26.b.3.A',3,'When feeling sad, a healthy method of expressing emotions is...','["hiding every feeling", "yelling at others", "breaking things", "talking to a trusted friend or writing in a journal"]'::jsonb,3,'Healthy expression helps feelings pass.','original'),
('115.26.b.3.B',3,'A healthy response to conflict with a friend is to...','["listen and find a solution together", "ignore the friend for weeks", "spread rumors", "hit the friend"]'::jsonb,0,'Problem-solving keeps friendships strong.','original'),
('115.26.b.3.B',3,'Which step helps cool down during conflict?','["raising your voice", "taking a few deep breaths before replying", "texting insults", "walking in and shouting"]'::jsonb,1,'Calming first leads to better outcomes.','original'),
('115.26.b.3.C',3,'Negative peer influence is when someone...','["invites you to a study group", "shares a snack", "pushes you to do something unsafe or against your values", "helps with homework"]'::jsonb,2,'Negative influence pressures harmful choices.','original'),
('115.26.b.3.D',3,'To talk to a parent about an important issue, a student should...','["avoid the topic forever", "wait until they are angry", "text rumors", "choose a calm time and be honest"]'::jsonb,3,'A calm, honest talk builds understanding.','original'),
('115.26.b.3.D',3,'Understanding another person''s point of view begins with...','["asking questions and listening", "ending the talk", "assuming you know", "interrupting"]'::jsonb,0,'Curious questions reveal perspective.','original'),
('115.26.b.3.E',3,'Good listening includes...','["talking over them", "making eye contact and not interrupting", "planning your reply while they talk", "looking at your phone"]'::jsonb,1,'Respectful listening shows care.','original'),
('115.26.b.3.E',3,'Respecting someone else''s feelings means...','["laughing at them", "telling them they are wrong to feel that way", "accepting that they may feel differently than you", "ignoring them"]'::jsonb,2,'Feelings are valid even when different.','original'),
('115.26.b.3.F',3,'A non-violent way to settle a disagreement is...','["threats", "a fight", "name calling", "negotiation or compromise"]'::jsonb,3,'Compromise solves conflict without harm.','original'),
('115.26.b.3.F',3,'A peer mediator helps classmates by...','["guiding them to talk and find a fair solution", "blaming one side", "picking a winner by force", "telling everyone the secrets"]'::jsonb,0,'Mediation is a non-violent skill.','original'),
('115.26.b.4.A',3,'During puberty, mood swings and body changes may affect a teen''s...','["blood type", "self-esteem", "eye color", "height at birth"]'::jsonb,1,'Changes can alter how teens see themselves.','original'),
('115.26.b.4.A',3,'A way to support healthy self-esteem during changes is to...','["compare yourself to online images", "hide from friends", "focus on strengths and avoid constant comparison", "tease others"]'::jsonb,2,'Positive self-talk supports confidence.','original'),
('115.26.b.4.B',3,'A long-term goal such as training for a 5K can lead to health benefits like...','["instant fitness", "less sleep needed", "no effort needed", "stronger heart and lungs"]'::jsonb,3,'Goals build habits that help health.','original'),
('115.26.b.4.B',3,'Setting a goal of eating fruit with every meal could help build...','["a healthy lifelong habit", "weaker teeth", "less energy", "a skipped breakfast"]'::jsonb,0,'Small goals build lasting habits.','original'),
('115.26.b.4.C',3,'A personal life goal is one that is...','["chosen by a stranger", "meaningful to you and has steps to reach it", "impossible to plan", "unwritten forever"]'::jsonb,1,'Goals work best with plans.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Health Education' and d.language = 'en'
on conflict (fingerprint) do nothing;
